"""Final YouTube thumbnail generated by GPT Image 2.5 Sunburst with the Arabic phrase rendered natively.

The text-free ``10_background.png`` (also the video background) goes in as the reference image; the model
returns the finished 1920x1080 thumbnail, which is kept as returned: no code draws text or resizes it afterwards.
"""

from __future__ import annotations

import io
import json
import re
import time
from pathlib import Path

import vercel_gateway as gateway
from PIL import Image, ImageFilter, ImageStat

THUMBNAIL_FILE = "11_thumbnail_base.jpg"
BACKGROUND_FILE = "10_background.png"
OUTPUT_SIZE = (1920, 1080)
MAX_SUNBURST_THUMBNAIL_ATTEMPTS = 4
YOUTUBE_THUMBNAIL_MAX_BYTES = 2_000_000  # YouTube rejects thumbnails over 2 MB
JPEG_QUALITIES = (95, 92, 88, 84, 80, 75, 70)
ATTEMPT_LOG = "thumbnail_attempts.json"
RETRYABLE = (gateway.REQUEST_FAILED, gateway.BAD_RESPONSE)


class ThumbnailError(RuntimeError):
    pass


def build_prompt(thumbnail_text: str) -> str:
    return f"""Turn the attached reference image into a finished cinematic YouTube thumbnail (16:9) for a calm Arabic history channel.

EXACT ARABIC TEXT: «{thumbnail_text}»

Render exactly this Arabic phrase and no other text.
- Preserve the spelling exactly, with properly connected Arabic letters and correct right-to-left rendering.
- Do not translate it, paraphrase it, shorten it or change any letter or diacritic.
- Do not add any other text: no Latin letters, no extra Arabic words, no gibberish, no duplicated title, no numbers, no watermark, no logo.

Keep the historical subject, the historical period, the overall visual identity and the important scene content of the reference image. Do not invent a different place or era.

Design: the phrase is part of the artwork itself, integrated naturally into the composition and the lighting, as if one designer made the whole thumbnail. Large, bold, mobile-first readable Arabic typography with strong contrast created naturally by the composition and light. One clear focal point; the text occupies a sensible area and never covers the focal subject. Calm, atmospheric, visually compelling but not clickbait. Keep all important content away from the extreme top and bottom edges.

Strictly forbidden: black card, black rectangle, text box, banner, pill, opaque panel, UI-like overlay, caption bar, frame, border, artificial dark block, solid dark patch."""


def decode_image(data: bytes) -> Image.Image:
    """Decode the model output. It must already be exactly 1920x1080: nothing is cropped or resized."""
    image = Image.open(io.BytesIO(data))
    image.load()
    image = image.convert("RGB")
    if image.size != OUTPUT_SIZE:
        raise ValueError(f"unexpected thumbnail size {image.size}")
    return image


def save_jpeg(image: Image.Image, path: Path) -> int:
    """Lossy compression only (never a resize) until the file fits YouTube's 2 MB limit; returns the quality used."""
    for quality in JPEG_QUALITIES:
        image.save(path, format="JPEG", quality=quality, optimize=True)
        if path.stat().st_size <= YOUTUBE_THUMBNAIL_MAX_BYTES:
            return quality
    raise RuntimeError("thumbnail exceeds YouTube's 2 MB limit even at the lowest JPEG quality")


def validate_thumbnail(image: Image.Image) -> None:
    """Same visual-quality guard as the background (flat or blank images are rejected), at thumbnail size."""
    if image.size != OUTPUT_SIZE:
        raise RuntimeError(f"Unexpected thumbnail size: {image.size}")
    gray = image.convert("L")
    contrast = ImageStat.Stat(gray).stddev[0]
    edges = ImageStat.Stat(gray.filter(ImageFilter.FIND_EDGES)).mean[0]
    if contrast < 18 or edges < 2.0:
        raise RuntimeError(f"Generated thumbnail failed the visual-quality guard (contrast={contrast:.1f}, edges={edges:.1f})")


def _log(story: Path, record: dict) -> None:
    path = story / "logs" / ATTEMPT_LOG
    path.parent.mkdir(parents=True, exist_ok=True)
    try:
        records = json.loads(path.read_text(encoding="utf-8")) if path.exists() else []
    except ValueError:
        records = []
    records.append(record)
    path.write_text(json.dumps(records, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")


def generate(story: Path, thumbnail_text: str, *, max_attempts: int = MAX_SUNBURST_THUMBNAIL_ATTEMPTS) -> dict:
    """Produce ``11_thumbnail_base.jpg``; stops after the first valid candidate and never exceeds 4 attempts."""
    if len(re.findall(r"[ء-ي]+", thumbnail_text)) not in (2, 3, 4):
        raise ThumbnailError("THUMBNAIL_TEXT_FAILED: expected 2-4 Arabic words")
    key = gateway.api_key()  # raises VERCEL_KEY_MISSING; no other provider is tried
    reference = (story / BACKGROUND_FILE).read_bytes()
    prompt = build_prompt(thumbnail_text)
    attempts = min(int(max_attempts), MAX_SUNBURST_THUMBNAIL_ATTEMPTS)
    last_error = "no attempt made"
    for number in range(1, attempts + 1):
        record = {"attempt": number, "model": gateway.MODEL}
        try:
            data = gateway.edit_image(key, prompt, reference)
            image = decode_image(data)
            validate_thumbnail(image)
        except gateway.GatewayError as exc:
            _log(story, {**record, "outcome": "error", "code": exc.code})
            if exc.code in gateway.STOP_CODES or exc.code == gateway.BAD_REQUEST:
                raise  # no image was made: retrying a rejected request would only repeat it
            last_error = exc.code
            time.sleep(min(5 * number, 20))
            continue
        except (OSError, ValueError, RuntimeError) as exc:
            _log(story, {**record, "outcome": "invalid_image", "detail": type(exc).__name__})
            last_error = "VERCEL_INVALID_IMAGE"
            continue
        quality = save_jpeg(image, story / THUMBNAIL_FILE)
        _log(story, {**record, "outcome": "passed"})
        return {
            "thumbnail_generation_provider": "vercel_ai_gateway",
            "thumbnail_model": gateway.MODEL,
            "thumbnail_text_render_method": "native_in_generated_image",
            "thumbnail_attempts": number,
            "thumbnail_size": f"{OUTPUT_SIZE[0]}x{OUTPUT_SIZE[1]}",
            "thumbnail_generation_quality": gateway.IMAGE_QUALITY,
            "thumbnail_jpeg_quality": quality,
            "thumbnail_text_ocr_verified": False,  # no reliable Arabic OCR here: owner review is the final text check
        }
    raise gateway.GatewayError(gateway.REQUEST_FAILED, f"no valid thumbnail after {attempts} attempts ({last_error})")
